#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {10, 20, 30};

    // Use size_type for correctness
    std::vector<int>::size_type s = v.size();
    std::cout << "Size: " << s << "\n";

    // Use difference_type for calculating distance
    auto it1 = v.begin();
    auto it2 = v.end();
    std::vector<int>::difference_type diff = std::distance(it1, it2);
    std::cout << "Difference: " << diff << "\n";

    // Demonstrating reverse iteration type
    std::vector<int>::reverse_iterator rit = v.rbegin();
    std::cout << "Reverse start: " << *rit << "\n";
}
